import React,{useEffect,useMemo,useState} from 'react';
import {AlertCircle,ArrowDown,ArrowUp,Download,FilePlus2,Layers3,Plus,Save,ShieldAlert,Trash2,Upload} from 'lucide-react';
import {dataService} from '../services/dataService';
import {writtenExamService} from '../services/writtenExamService';
import {A1_TEMPLATE,L135_TEMPLATE,WrittenExam,WrittenQuestion,WrittenSection,createQuestion,createSection,getWrittenExamTotals,getDefaultWrittenQuestionTimeLimit,makeId,validateWrittenExam} from '../utils/writtenExam';
import {getQuestionExpectedAnswers} from '../utils/quizAnswerMatcher';
import {getCorrectReorderIds} from '../utils/quizReorder';
import {VerbesTrousEditor} from '../components/verbesTrous/VerbesTrousEditor';
import {WrittenExamCopy,downloadWrittenExamCopyPdf} from '../components/WrittenExamCopy';
import type {Quiz,QuizQuestion} from '../types';

const card='rounded-2xl border border-[#d8e6ee] bg-white p-4 shadow-sm';
const blankExam=():WrittenExam=>({...JSON.parse(JSON.stringify(L135_TEMPLATE)),id:undefined,title:'Nouvel examen',description:'',class_ids:[],sections:[]});
const localDate=(v?:string|null)=>{if(!v)return '';const d=new Date(v);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
const toIso=(v:string)=>v?new Date(v).toISOString():null;
const stripJsonComments=(v:string)=>v.replace(/\/\*[\s\S]*?\*\//g,'').split('\n').map(line=>line.replace(/(^|\s)\/\/.*$/,'')).join('\n').replace(/,\s*([}\]])/g,'$1');
const fromQuiz=(quiz:Quiz,q:QuizQuestion):WrittenQuestion=>{
 const base:any={id:makeId(),type:q.type,prompt:q.question,points:Number(q.points)||1,source_quiz_id:quiz.id,source_question_id:q.id,explanation:q.explanation,time_limit_seconds:Number(q.time_limit_seconds)||getDefaultWrittenQuestionTimeLimit(q)};
 if(q.type==='qcm'){const options=(q.options||[]).map(label=>({id:makeId(),label}));const raw=String(q.correct_answer||'').trim();const letterIndex=/^[A-Z]$/i.test(raw)?raw.toUpperCase().charCodeAt(0)-65:-1;const numericIndex=/^\d+$/.test(raw)?Number(raw):-1;const index=options.findIndex(o=>o.label===raw);const correctIndex=index>=0?index:letterIndex>=0&&letterIndex<options.length?letterIndex:numericIndex>=0&&numericIndex<options.length?numericIndex:-1;return {...base,options,answer_key:{correctOptionId:correctIndex>=0?options[correctIndex].id:''}};}
 if(q.type==='reorder')return {...base,items:(q.items||[]).map(x=>({...x})),answer_key:{correctOrder:getCorrectReorderIds(q)}};
 if(q.type==='verbes_trous')return {...base,points:(q.verbes_trous?.phrases?.length||0)*3,verbes_trous:q.verbes_trous,answer_key:{phrases:(q.verbes_trous?.phrases||[]).map(p=>({...p,verbe:p.verbe||'',reponses:p.reponses||[]})) as any}};
 const expected=getQuestionExpectedAnswers(q);return expected.length>1?{...base,blank_count:expected.length,answer_key:{answers:expected.map(x=>x.split(/\s*[\/;|]\s*/).filter(Boolean))}}:{...base,answer_key:{acceptedAnswers:(expected[0]||'').split(/\s*[\/;|]\s*/).filter(Boolean)}};
};
const mapDefinition=(data:any):WrittenExam=>{
 const v=(data.versions||[])[0];const sections=(v?.written_exam_sections||[]).sort((a:any,b:any)=>a.position-b.position).map((s:any)=>({id:s.section_key,title:s.title,instructions:s.instructions||'',category:s.category||'',points:Number(s.max_points)||0,shuffle:s.shuffle!==false,group_name:s.group_name||'',fixed_position:!!s.fixed_position,support_text:s.support_text||'',support_url:s.support_url||'',questions:(s.written_exam_questions||[]).sort((a:any,b:any)=>a.position-b.position).map((q:any)=>{const row=Array.isArray(q.written_exam_answer_keys)?q.written_exam_answer_keys[0]:q.written_exam_answer_keys;return {...(q.public_data||{}),id:q.question_key,db_id:q.id,type:q.question_type,prompt:q.prompt,points:Number(q.points),time_limit_seconds:Number(q.public_data?.time_limit_seconds)||getDefaultWrittenQuestionTimeLimit({type:q.question_type}),answer_key:row?.answer_key||{},explanation:row?.explanation||'',manual_review:!!q.manual_review,source_quiz_id:q.source_quiz_id,source_question_id:q.source_question_id};})}));
 return {id:data.id,title:v?.title||data.title,description:v?.description??data.description??'',level:v?.level||data.level||'',target_language:v?.target_language||data.target_language||'it',instruction_language:v?.instruction_language||data.instruction_language||'fr',duration_minutes:v?.duration_minutes||data.duration_minutes,class_ids:(data.written_exam_classes||[]).map((x:any)=>x.class_id),opens_at:v?.opens_at??data.opens_at,closes_at:v?.closes_at??data.closes_at,status:data.status,display_scale:(v?.display_scale??data.display_scale)===null?null:Number(v?.display_scale??data.display_scale),expression_writing_max_points:Number(v?.expression_writing_max_points)||0,max_attempts:v?.max_attempts||data.max_attempts||1,shuffle_sections:v?.shuffle_sections??data.shuffle_sections,shuffle_questions:v?.shuffle_questions??data.shuffle_questions,shuffle_options:v?.shuffle_options??data.shuffle_options,navigation_mode:'sequential',show_score_after_publish:v?.show_score_after_publish??data.show_score_after_publish,show_corrections_after_publish:v?.show_corrections_after_publish??data.show_corrections_after_publish,integrity_settings:v?.integrity_settings||data.integrity_settings||{fullscreen:false,warn_on_tab_switch:true,watermark:false},sections};
};
export const WrittenExamsView:React.FC<{classes:Array<{id:string;name:string}>}> = ({classes})=>{
 const [exams,setExams]=useState<any[]>([]);const [exam,setExam]=useState<WrittenExam|null>(null);const [loading,setLoading]=useState(true);const [saving,setSaving]=useState(false);
 const [error,setError]=useState('');const [message,setMessage]=useState('');const [quizzes,setQuizzes]=useState<Quiz[]>([]);const [sourceQuizId,setSourceQuizId]=useState('');
 const [selectedExamId,setSelectedExamId]=useState('');const [attempts,setAttempts]=useState<any[]>([]);const [events,setEvents]=useState<any[]>([]);const [definitionData,setDefinitionData]=useState<any|null>(null);
 const [selectedAttempt,setSelectedAttempt]=useState<any|null>(null);const [manualQuestions,setManualQuestions]=useState<any[]>([]);const [manualScores,setManualScores]=useState<Record<string,number>>({});const [expressionWritingScore,setExpressionWritingScore]=useState<string>('');const [answerJsonDraft,setAnswerJsonDraft]=useState<Record<string,string>>({});const [showImportPanel,setShowImportPanel]=useState(false);const [jsonDraft,setJsonDraft]=useState('');
 const totals=useMemo(()=>exam?getWrittenExamTotals(exam):{raw:0,planned:0,normalized:null,normalizedMaximum:null},[exam]);
 const refresh=async()=>{try{setExams(await writtenExamService.listTeacherExams());}catch(e){setError(e instanceof Error?e.message:'Chargement impossible.');}finally{setLoading(false);}};
 useEffect(()=>{void refresh();setQuizzes(dataService.getQuizzes());},[]);
 const start=(template?:WrittenExam)=>{setAnswerJsonDraft({});setExam(template?JSON.parse(JSON.stringify(template)):blankExam());setSelectedExamId('');setSelectedAttempt(null);setError('');setMessage('');};
 const edit=async(id:string)=>{try{setAnswerJsonDraft({});const data=await writtenExamService.getDefinition(id);setExam(mapDefinition(data));setSelectedExamId(id);setSelectedAttempt(null);setError('');}catch(e){setError(e instanceof Error?e.message:'Lecture impossible.');}};
 const openResults=async(id:string)=>{try{setExam(null);setSelectedExamId(id);setSelectedAttempt(null);const [rows,def]=await Promise.all([writtenExamService.listAttempts(id),writtenExamService.getDefinition(id)]);const logs=await writtenExamService.listIntegrityEvents(id).catch(()=>[]);setAttempts(rows);setEvents(logs);setDefinitionData(def);setManualQuestions([]);}catch(e){setError(e instanceof Error?e.message:'Chargement des résultats impossible.');}};
 const updateSection=(id:string,patch:Partial<WrittenSection>)=>setExam(e=>e?({...e,sections:e.sections.map(s=>s.id===id?({...s,...patch}):s)}):e);
 const updateQuestion=(sid:string,id:string,patch:Partial<WrittenQuestion>)=>setExam(e=>e?({...e,sections:e.sections.map(s=>s.id===sid?({...s,questions:s.questions.map(q=>q.id===id?({...q,...patch}):q)}):s)}):e);
 const addQuizQuestions=(sid:string)=>{const quiz=quizzes.find(q=>q.id===sourceQuizId);if(!quiz)return;const imported=quiz.questions.map(q=>fromQuiz(quiz,q));setExam(e=>e?({...e,sections:e.sections.map(s=>s.id===sid?({...s,questions:[...s.questions,...imported]}):s)}):e);setMessage(imported.length+' question(s) copiée(s) depuis le quiz. Le contenu est figé dans ce sujet.');};
 const save=async(publish=false)=>{if(!exam)return;const issues=validateWrittenExam(exam);const activeQuestionIds=new Set(exam.sections.flatMap(s=>s.questions.filter(q=>q.type==='text').map(q=>q.id)));const invalidMultiBlank=Object.entries(answerJsonDraft).some(([id,raw])=>activeQuestionIds.has(id)&&raw.trim().length>0&&(()=>{if(!raw.trim())return false;try{const parsed=JSON.parse(raw);return !Array.isArray(parsed)||parsed.some((item:any)=>!Array.isArray(item));}catch{return true;}})());if(invalidMultiBlank){setError('Une clé de correction multi-trous contient un JSON invalide.');return;}if(issues.length){setError(issues.slice(0,8).join(' '));return;}setSaving(true);setError('');try{const saved=await writtenExamService.saveDefinition(exam);if(publish){await writtenExamService.publish(saved.exam_id,saved.version_id);setMessage('Version '+saved.version_number+' publiée.');}else setMessage('Brouillon enregistré, version '+saved.version_number+'.');setExam(null);await refresh();}catch(e){setError(e instanceof Error?e.message:'Enregistrement impossible.');}finally{setSaving(false);}};
 const applyImportedJson=(raw:string)=>{try{const parsed=JSON.parse(stripJsonComments(raw));if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))throw new Error('La racine du fichier doit être un objet JSON.');if(!Array.isArray(parsed.sections))throw new Error('Le champ sections doit être un tableau.');setAnswerJsonDraft({});const defaults=blankExam();setExam({...defaults,...parsed,id:undefined,status:'draft',integrity_settings:{...defaults.integrity_settings,...(parsed.integrity_settings||{})},sections:parsed.sections});setError('');setMessage('Sujet importé comme nouveau brouillon. Vérifiez les classes, les réponses et le barème avant l’enregistrement.');setShowImportPanel(false);setJsonDraft('');}catch(e){setError('JSON/JSONC invalide : '+(e instanceof Error?e.message:'Vérifiez la syntaxe du fichier.'));}};
 const importJson=async(file?:File)=>{if(!file)return;try{applyImportedJson(await file.text());}catch(e){setError('Lecture du fichier impossible : '+(e instanceof Error?e.message:''));}};
 const exportJson=()=>{if(!exam)return;const blob=new Blob([JSON.stringify(exam,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='examen-ecrit.json';a.click();URL.revokeObjectURL(url);};
 const grade=async()=>{if(!selectedAttempt)return;try{if(manualQuestions.length)await writtenExamService.grade(selectedAttempt.id,manualScores);const selectedVersion=definitionData?.versions?.find((v:any)=>v.id===selectedAttempt.version_id);if(Number(selectedVersion?.expression_writing_max_points||0)>0){if(expressionWritingScore==='')throw new Error('Saisissez la note d’expression écrite avant de finaliser la correction.');await writtenExamService.gradeExpressionWriting(selectedAttempt.id,Number(expressionWritingScore));}setMessage('Correction enregistrée.');const rows=await writtenExamService.listAttempts(selectedExamId);setAttempts(rows);setSelectedAttempt(rows.find(a=>a.id===selectedAttempt.id)||null);}catch(e){setError(e instanceof Error?e.message:'Correction impossible.');}};
 const toggleClass=(classId:string,checked:boolean)=>setExam(current=>current?({...current,class_ids:checked?Array.from(new Set([...current.class_ids,classId])):current.class_ids.filter(id=>id!==classId)}):current);
 const applyTemplateToCurrent=(template:WrittenExam)=>{if(!exam?.id)return;const confirmed=window.confirm('Remplacer le contenu du sujet « '+exam.title+' » par le modèle « '+template.title+' » ? Les classes et dates seront conservées. Les anciennes tentatives restent liées à leur version; elles ne seront supprimées que par la réinitialisation explicite.');if(!confirmed)return;setAnswerJsonDraft({});setExam({...JSON.parse(JSON.stringify(template)),id:exam.id,title:exam.title,class_ids:[...exam.class_ids],opens_at:exam.opens_at??null,closes_at:exam.closes_at??null,status:'draft'});setMessage('Modèle chargé dans une nouvelle version en brouillon. Vérifiez les classes puis enregistrez ou publiez.');};
 const selectedExam=exams.find(item=>item.id===selectedExamId);
 const resetAttempts=async()=>{if(!selectedExam||!['closed','grading'].includes(selectedExam.status)){setError('Clôturez le sujet avant de réinitialiser ses tentatives.');return;}const confirmed=window.confirm('SUPPRESSION DÉFINITIVE — Réinitialiser toutes les tentatives du sujet « '+selectedExam.title+' » ('+attempts.length+') ? Les réponses, notes, résultats et journaux d’intégrité, y compris ceux des tentatives en cours, seront supprimés. Le sujet, ses versions et ses affectations de classes seront conservés.');if(!confirmed)return;setError('');try{const result=await writtenExamService.resetAttempts(selectedExamId);setSelectedAttempt(null);setManualQuestions([]);setManualScores({});await openResults(selectedExamId);setMessage((result.deleted_attempts||0)+' tentative(s) et leurs données associées supprimées pour « '+selectedExam.title+' ».');}catch(e){setError(e instanceof Error?e.message:'Réinitialisation impossible.');}};
 const average=attempts.filter(a=>a.raw_score!==null).length?attempts.filter(a=>a.raw_score!==null).reduce((n,a)=>n+Number(a.raw_score),0)/attempts.filter(a=>a.raw_score!==null).length:0;
 const sectionStats=useMemo(()=>{const stats=new Map<string,{score:number;max:number;count:number}>();attempts.forEach(a=>(a.written_exam_section_results||[]).forEach((r:any)=>{const old=stats.get(r.section_id)||{score:0,max:0,count:0};old.score+=Number(r.raw_score||0);old.max+=Number(r.raw_max||0);old.count+=1;stats.set(r.section_id,old);}));return Array.from(stats.entries()).map(([id,v])=>({id,...v,rate:v.max?Number((v.score/v.max*100).toFixed(1)):0}));},[attempts]);
 const exportResultsCsv=()=>{const headers=['student_id','first_name','last_name','student_number','attempt','status','raw_score','raw_max','expression_writing_score','expression_writing_max_points','normalized_score','started_at','submitted_at'];const rows=attempts.map(a=>[a.student_id,a.students?.first_name||'',a.students?.last_name||'',a.students?.student_number||'',a.attempt_number,a.status,a.raw_score??'',a.raw_max,a.expression_writing_score??'',a.expression_writing_max_points??0,a.normalized_score??'',a.started_at,a.submitted_at||'']);const csv=[headers,...rows].map(row=>row.map(value=>'"'+String(value).replace(/"/g,'""')+'"').join(';')).join('\n');const blob=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='resultats-examen-ecrit.csv';link.click();URL.revokeObjectURL(url);};
 return <div className="mx-auto w-full max-w-[1440px] space-y-6">
  <header className="flex flex-col gap-4 rounded-2xl border border-[#d8e6ee] bg-gradient-to-br from-white via-white to-[#f1f7fa] p-4 shadow-sm sm:flex-row sm:items-center sm:justify-between sm:p-6"><div><p className="text-xs font-bold uppercase tracking-widest text-[#2fa36b]">Évaluation écrite composite</p><h1 className="mt-1 text-2xl font-black tracking-tight text-[#072a3f] sm:text-3xl">Examens écrits</h1><p className="mt-1 text-sm text-slate-500">Création libre, réutilisation des quiz, publication des versions et correction des tentatives.</p></div><button onClick={()=>start()} className="inline-flex min-h-11 w-full items-center justify-center rounded-xl bg-[#072a3f] px-5 py-3 text-sm font-bold text-white shadow-sm transition hover:bg-[#0b3c5d] sm:w-auto"><Plus className="mr-1 inline h-4 w-4"/>Nouvel examen</button></header>
  {error&&<div role="alert" className="rounded-xl border border-rose-200 bg-rose-50 p-3 text-sm text-rose-800"><AlertCircle className="mr-1 inline h-4 w-4"/>{error}</div>}
  {message&&<div role="status" className="rounded-xl border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-800">{message}</div>}
  {exam?<section className={card+' space-y-5 sm:p-6'}>
   <div className="sticky top-0 z-20 -mx-4 flex flex-col gap-3 border-b border-[#d8e6ee] bg-white/95 px-4 py-3 backdrop-blur sm:-mx-6 sm:flex-row sm:items-center sm:justify-between sm:px-6"><div><p className="text-[10px] font-bold uppercase tracking-wider text-[#2fa36b]">Concepteur de sujet</p><h2 className="font-bold text-[#072a3f]">Éditeur d’examen</h2></div><div className="flex flex-wrap gap-2">{exam.id&&<details className="rounded-lg border px-3 py-2 text-xs"><summary className="cursor-pointer font-semibold">Modèle</summary><div className="mt-2 flex flex-wrap gap-2"><button type="button" onClick={()=>applyTemplateToCurrent(L135_TEMPLATE)} disabled={!exam.id} className="rounded border px-2 py-1 disabled:opacity-40">Appliquer L135</button><button type="button" onClick={()=>applyTemplateToCurrent(A1_TEMPLATE)} disabled={!exam.id} className="rounded border px-2 py-1 disabled:opacity-40">Appliquer A1</button></div><p className="mt-2 max-w-xs text-[11px] text-slate-500">Remplace le contenu du sujet en cours par un modèle mis à jour; conserve son titre, ses classes et ses dates.</p></details>}<button onClick={exportJson} className="rounded-lg border px-3 py-2 text-xs"><Download className="mr-1 inline h-3.5 w-3.5"/>Exporter</button><button type="button" onClick={()=>setShowImportPanel(v=>!v)} className="rounded-lg border border-[#2fa36b] px-3 py-2 text-xs font-semibold text-[#176b45]"><Upload className="mr-1 inline h-3.5 w-3.5"/>Importer / coller JSON</button><label className="cursor-pointer rounded-lg border px-3 py-2 text-xs">Fichier JSON/JSONC<input type="file" accept=".json,.jsonc,application/json" className="hidden" onChange={e=>{void importJson(e.target.files?.[0]);e.currentTarget.value='';}}/></label></div></div>
   {showImportPanel&&<section className="space-y-3 rounded-xl border border-[#b9d8c9] bg-[#f6fbf8] p-3" aria-label="Importer un sujet JSON">
    <div><h3 className="font-bold text-[#072a3f]">Importer un sujet depuis du texte JSON</h3><p className="mt-1 text-xs text-slate-600">Collez le contenu complet de votre fichier .json ou .jsonc ci-dessous. L’import crée un nouveau brouillon sans publier ni modifier un sujet déjà enregistré.</p></div>
    <textarea aria-label="Contenu JSON ou JSONC du sujet" rows={12} spellCheck={false} value={jsonDraft} onChange={e=>setJsonDraft(e.target.value)} placeholder={'{\n  "title": "Verifica A1",\n  "duration_minutes": 60,\n  "sections": []\n}'} className="w-full rounded-lg border border-slate-300 bg-white p-3 font-mono text-xs leading-5"/>
    <div className="flex flex-wrap items-center justify-between gap-2"><a href="https://github.com/AinaPercky/esame-italiano/blob/feat/written-composite-exams/docs/written-exams-json.md" target="_blank" rel="noreferrer" className="text-xs font-semibold text-[#176b45] underline">Ouvrir le guide complet de création JSON/JSONC ↗</a><div className="flex gap-2"><button type="button" onClick={()=>setJsonDraft('')} className="rounded-lg border bg-white px-3 py-2 text-xs">Effacer</button><button type="button" disabled={!jsonDraft.trim()} onClick={()=>applyImportedJson(jsonDraft)} className="rounded-lg bg-[#072a3f] px-4 py-2 text-xs font-bold text-white disabled:cursor-not-allowed disabled:opacity-40">Charger le sujet</button></div></div>
    <details className="rounded-lg border border-[#d8e6ee] bg-white p-3"><summary className="cursor-pointer text-sm font-semibold text-[#072a3f]">Guide rapide : format et types de questions</summary><div className="mt-3 space-y-3 text-xs leading-5 text-slate-700">
     <p><strong>Structure obligatoire :</strong> un objet JSON avec les paramètres du sujet et un tableau <code>sections</code>. Chaque section contient un tableau <code>questions</code>.</p>
     <pre className="overflow-x-auto rounded-lg bg-slate-50 p-3 text-[11px]">{'{\n  "title": "Verifica A1",\n  "level": "A1",\n  "target_language": "it",\n  "instruction_language": "fr",\n  "duration_minutes": 60,\n  "class_ids": ["UUID_DE_CLASSE"],\n  "display_scale": 100,\n  "max_attempts": 1,\n  "navigation_mode": "free",\n  "sections": [{\n    "id": "grammaire",\n    "title": "Grammaire",\n    "points": 10,\n    "questions": []\n  }]\n}'}</pre>
     <p><strong>Paramètres principaux :</strong> <code>title</code> (titre), <code>level</code> (A1–C2), <code>duration_minutes</code> (durée), <code>class_ids</code> (identifiants réels des classes), <code>opens_at</code> et <code>closes_at</code> (dates ISO ou null), <code>display_scale</code> (échelle facultative), <code>max_attempts</code>, <code>shuffle_sections</code>, <code>shuffle_questions</code>, <code>shuffle_options</code>, <code>navigation_mode</code> (<code>free</code> ou <code>sequential</code>).</p>
     <p><strong>Dans une section :</strong> <code>id</code>, <code>title</code>, <code>instructions</code>, <code>category</code>, <code>group_name</code>, <code>points</code> (0 = sans plafond), <code>shuffle</code>, <code>fixed_position</code>, <code>support_text</code>, <code>support_url</code> (lien HTTP/HTTPS), et <code>questions</code>.</p>
     <ul className="list-disc space-y-1 pl-5"><li><strong>QCM / vrai-faux :</strong> <code>type: "qcm"</code>, au moins deux <code>options</code> avec <code>id</code> et <code>label</code>, puis <code>answer_key.correctOptionId</code> qui référence l’identifiant de la bonne option.</li><li><strong>Réponse courte :</strong> <code>type: "text"</code> et <code>answer_key.acceptedAnswers</code>, une liste de réponses acceptées.</li><li><strong>Plusieurs trous :</strong> ajouter <code>blank_count</code> et <code>answer_key.answers</code>, avec une liste de variantes par trou dans l’ordre.</li><li><strong>Réordonnement :</strong> <code>type: "reorder"</code>, des <code>items</code> identifiés, puis <code>answer_key.correctOrder</code> contenant leurs identifiants dans le bon ordre.</li><li><strong>Correction manuelle :</strong> ajouter <code>manual_review: true</code> à la question.</li></ul>
     <p><strong>Temps et anti-triche :</strong> chaque question possède son propre compte à rebours via <code>time_limit_seconds</code> (1 à 3600 secondes, 17 s pour QCM/réordonnancement, 32 s pour texte/verbes à trous par défaut). L’ordre des questions est aléatoire et propre à chaque élève. La progression est séquentielle, sans retour en arrière ; à la fin du délai, la réponse est verrouillée et la question suivante s’ouvre automatiquement.</p><p><strong>Points importants :</strong> chaque question doit avoir un identifiant unique, un énoncé et un nombre de points positif. Le total brut est calculé à partir des points des questions ; <code>sections[].points</code> est un plafond indicatif. Les clés de correction restent privées et ne sont pas envoyées à l’élève pendant l’épreuve.</p>
     <p className="rounded-lg bg-amber-50 p-2 text-amber-900"><strong>À savoir :</strong> l’import PDF automatique n’est pas disponible. Utilisez le texte du document ou un lien HTTP/HTTPS comme support. Après import, vérifiez les classes, les réponses attendues, le nombre de trous, les identifiants et le barème avant de sauvegarder et publier.</p>
    </div></details>
   </section>}
   <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
    <label className="text-xs font-semibold">Titre<input className="mt-1 w-full rounded-lg border p-2 text-sm" value={exam.title} onChange={e=>setExam({...exam,title:e.target.value})}/></label>
    <label className="text-xs font-semibold">Niveau CECRL<input className="mt-1 w-full rounded-lg border p-2 text-sm" placeholder="A1, A2, B1…" value={exam.level} onChange={e=>setExam({...exam,level:e.target.value})}/></label>
    <label className="text-xs font-semibold">Durée globale (minutes)<input type="number" min="1" className="mt-1 w-full rounded-lg border p-2 text-sm" value={exam.duration_minutes} onChange={e=>setExam({...exam,duration_minutes:Number(e.target.value)})}/></label>
    <label className="text-xs font-semibold">Langue cible<input className="mt-1 w-full rounded-lg border p-2 text-sm" value={exam.target_language} onChange={e=>setExam({...exam,target_language:e.target.value})}/></label>
    <label className="text-xs font-semibold">Langue des consignes<input className="mt-1 w-full rounded-lg border p-2 text-sm" value={exam.instruction_language} onChange={e=>setExam({...exam,instruction_language:e.target.value})}/></label>
    <label className="text-xs font-semibold">Note d’expression écrite (incluse dans le total sur 100)<select className="mt-1 w-full rounded-lg border p-2 text-sm" value={exam.expression_writing_max_points??0} onChange={e=>setExam({...exam,expression_writing_max_points:Number(e.target.value) as 0|10|20,display_scale:Number(e.target.value)>0?100:exam.display_scale})}><option value={0}>Aucune</option><option value={10}>Sur 10 points</option><option value={20}>Sur 20 points</option></select></label><label className="text-xs font-semibold">Échelle normalisée (facultative)<input type="number" min="1" className="mt-1 w-full rounded-lg border p-2 text-sm" placeholder="Désactivée" value={exam.display_scale??''} onChange={e=>setExam({...exam,display_scale:e.target.value?Number(e.target.value):null})}/></label>
    <label className="text-xs font-semibold">Ouverture<input type="datetime-local" className="mt-1 w-full rounded-lg border p-2 text-sm" value={localDate(exam.opens_at)} onChange={e=>setExam({...exam,opens_at:toIso(e.target.value)})}/></label>
    <label className="text-xs font-semibold">Fermeture<input type="datetime-local" className="mt-1 w-full rounded-lg border p-2 text-sm" value={localDate(exam.closes_at)} onChange={e=>setExam({...exam,closes_at:toIso(e.target.value)})}/></label>
    <label className="text-xs font-semibold">Nombre de tentatives<input type="number" min="1" max="10" className="mt-1 w-full rounded-lg border p-2 text-sm" value={exam.max_attempts} onChange={e=>setExam({...exam,max_attempts:Number(e.target.value)})}/></label><div className="rounded-lg border border-[#b9d8c9] bg-[#f6fbf8] p-3 text-xs font-semibold text-[#176b45]">Navigation séquentielle obligatoire : une seule question à la fois, sans retour en arrière ni accès direct.</div>
    <label className="text-xs font-semibold sm:col-span-2 lg:col-span-3">Description<textarea rows={2} className="mt-1 w-full rounded-lg border p-2 text-sm" value={exam.description} onChange={e=>setExam({...exam,description:e.target.value})}/></label>
    <fieldset className="rounded-xl border border-[#d8e6ee] p-3 sm:col-span-2 lg:col-span-3"><legend className="px-1 text-xs font-semibold">Classes concernées — {exam.class_ids.length} sélectionnée(s)</legend><div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{classes.map(c=><label key={c.id} className="flex min-h-11 items-center gap-2 rounded-lg bg-slate-50 px-3 py-2 text-sm"><input type="checkbox" checked={exam.class_ids.includes(c.id)} onChange={e=>toggleClass(c.id,e.target.checked)} className="h-4 w-4 accent-[#2fa36b]"/>{c.name}</label>)}</div>{classes.length===0&&<p className="text-xs text-amber-700">Aucune classe disponible.</p>}<p className="mt-2 text-[11px] text-slate-500">Une ou plusieurs classes peuvent être sélectionnées. L’affectation s’applique à la nouvelle version publiée; les anciennes tentatives restent rattachées à leur version et classe d’origine.</p></fieldset>
   </div>
   <div className="grid gap-2 rounded-xl bg-[#f3f8fb] p-3 sm:grid-cols-4"><div><p className="text-[10px] uppercase text-slate-500">Questions + expression</p><p className="text-2xl font-black text-[#072a3f]">{totals.totalWithExpression} / {exam.expression_writing_max_points?100:totals.raw}</p></div><div><p className="text-[10px] uppercase text-slate-500">Allocation sections</p><p className="text-xl font-bold">{totals.planned}</p></div><div><p className="text-[10px] uppercase text-slate-500">Échelle</p><p className="text-xl font-bold">{exam.display_scale?'/'+exam.display_scale:'Brute'}</p></div><div><p className="text-[10px] uppercase text-slate-500">Durée</p><p className="text-xl font-bold">{exam.duration_minutes} min</p></div><p className="text-[11px] text-slate-500 sm:col-span-4">Le total final additionne les questions et la note d’expression écrite saisie par le professeur. Si l’expression est activée, les deux composantes doivent totaliser 100 points.</p></div>
   <div className="grid gap-2 rounded-xl border p-3 sm:grid-cols-2"><label className="flex items-center gap-2 text-xs"><input type="checkbox" checked={exam.shuffle_sections} onChange={e=>setExam({...exam,shuffle_sections:e.target.checked})}/>Mélanger les sections</label><p className="flex items-center gap-2 text-xs font-semibold text-[#176b45]"><ShieldAlert className="h-4 w-4"/>Ordre des questions aléatoire et propre à chaque élève</p><label className="flex items-center gap-2 text-xs"><input type="checkbox" checked={exam.shuffle_options} onChange={e=>setExam({...exam,shuffle_options:e.target.checked})}/>Mélanger options et éléments à réordonner</label><label className="flex items-center gap-2 text-xs"><input type="checkbox" checked={exam.show_score_after_publish} onChange={e=>setExam({...exam,show_score_after_publish:e.target.checked})}/>Afficher les scores après publication</label><label className="flex items-center gap-2 text-xs"><input type="checkbox" checked={exam.show_corrections_after_publish} onChange={e=>setExam({...exam,show_corrections_after_publish:e.target.checked})}/>Autoriser la correction après publication</label><p className="flex items-center gap-2 text-xs font-semibold text-[#0b3c5d]"><ShieldAlert className="h-4 w-4 text-[#2fa36b]"/>Plein écran obligatoire pendant chaque examen</p><label className="flex items-center gap-2 text-xs"><input type="checkbox" checked={exam.integrity_settings.watermark} onChange={e=>setExam({...exam,integrity_settings:{...exam.integrity_settings,watermark:e.target.checked}})}/>Filigrane dissuasif</label><label className="flex items-center gap-2 text-xs"><input type="checkbox" checked={exam.integrity_settings.warn_on_tab_switch} onChange={e=>setExam({...exam,integrity_settings:{...exam.integrity_settings,warn_on_tab_switch:e.target.checked}})}/>Journaliser les changements d’onglet/focus</label></div>
   <div className="space-y-3"><div className="flex items-center justify-between"><h3 className="font-bold text-[#072a3f]">Sections dynamiques</h3><button onClick={()=>setExam({...exam,sections:[...exam.sections,createSection()]})} className="rounded-lg border px-3 py-2 text-xs font-bold"><Plus className="mr-1 inline h-3.5 w-3.5"/>Section</button></div>
   {exam.sections.map((s,si)=><article key={s.id} className="rounded-xl border border-[#d8e6ee] p-3"><div className="grid gap-2 sm:grid-cols-[1fr_110px_auto]"><input className="rounded-lg border p-2 text-sm font-bold" value={s.title} onChange={e=>updateSection(s.id,{title:e.target.value})}/><label className="text-[10px]">Plafond (0 = sans limite)<input type="number" min="0" step=".5" className="mt-1 w-full rounded-lg border p-2" value={s.points} onChange={e=>updateSection(s.id,{points:Number(e.target.value)})}/></label><div className="flex items-end gap-1"><button disabled={!si} onClick={()=>setExam({...exam,sections:exam.sections.map((x,i)=>i===si?exam.sections[si-1]:i===si-1?exam.sections[si]:x)})} className="rounded-lg border p-2 disabled:opacity-30"><ArrowUp size={14}/></button><button disabled={si===exam.sections.length-1} onClick={()=>setExam({...exam,sections:exam.sections.map((x,i)=>i===si?exam.sections[si+1]:i===si+1?exam.sections[si]:x)})} className="rounded-lg border p-2 disabled:opacity-30"><ArrowDown size={14}/></button><button onClick={()=>setExam({...exam,sections:exam.sections.filter(x=>x.id!==s.id)})} className="rounded-lg p-2 text-rose-600"><Trash2 size={14}/></button></div></div>
    <div className="mt-2 grid gap-2 sm:grid-cols-2"><label className="text-xs">Catégorie libre<input className="mt-1 w-full rounded-lg border p-2" value={s.category||''} onChange={e=>updateSection(s.id,{category:e.target.value})}/></label><label className="text-xs">Groupe de sections (facultatif)<input className="mt-1 w-full rounded-lg border p-2" value={s.group_name||''} onChange={e=>updateSection(s.id,{group_name:e.target.value})} placeholder="Ex. Compréhension du texte"/></label><p className="pt-5 text-xs font-semibold text-[#176b45]">Questions mélangées automatiquement</p><label className="flex items-center gap-2 text-xs"><input type="checkbox" checked={!!s.fixed_position} onChange={e=>updateSection(s.id,{fixed_position:e.target.checked})}/>Conserver la position de la section</label></div>
    <textarea rows={2} className="mt-2 w-full rounded-lg border p-2 text-sm" placeholder="Consignes" value={s.instructions} onChange={e=>updateSection(s.id,{instructions:e.target.value})}/><textarea rows={3} className="mt-2 w-full rounded-lg border p-2 text-sm" placeholder="Texte-support partagé par les questions de cette section" value={s.support_text||''} onChange={e=>updateSection(s.id,{support_text:e.target.value})}/><input type="url" className="mt-2 w-full rounded-lg border p-2 text-sm" placeholder="Lien vers un document support PDF/image (facultatif)" value={s.support_url||''} onChange={e=>updateSection(s.id,{support_url:e.target.value})}/>
    <div className="mt-3 flex flex-wrap gap-2 rounded-lg bg-slate-50 p-2"><select className="min-w-0 flex-1 rounded-lg border p-2 text-xs" value={sourceQuizId} onChange={e=>setSourceQuizId(e.target.value)}><option value="">Copier les questions d’un quiz existant…</option>{quizzes.map(q=><option key={q.id} value={q.id}>{q.title}</option>)}</select><button disabled={!sourceQuizId} onClick={()=>addQuizQuestions(s.id)} className="rounded-lg border bg-white px-3 py-2 text-xs font-bold disabled:opacity-40"><FilePlus2 className="mr-1 inline h-3.5 w-3.5"/>Copier</button></div>
    <div className="mt-3 space-y-3">{s.questions.map((q,qi)=><div key={q.id} className="rounded-xl border p-3"><div className="grid gap-2 sm:grid-cols-[1fr_85px_125px_auto]"><textarea rows={2} className="rounded-lg border p-2 text-sm" value={q.prompt} onChange={e=>updateQuestion(s.id,q.id,{prompt:e.target.value})}/><input aria-label="Points" type="number" min=".25" step=".25" className="rounded-lg border p-2" value={q.points} onChange={e=>updateQuestion(s.id,q.id,{points:Number(e.target.value)})}/><select className="rounded-lg border p-2 text-xs" value={q.type} onChange={e=>{const type=e.target.value as WrittenQuestion['type'];const vt=type==='verbes_trous'?{titre:'Esercizio 6 – Verbi riflessivi e presente indicativo',consigne:'Choisissez le verbe qui convient, puis conjuguez-le au présent.',points_par_phrase:3,banque:[],phrases:[]}:undefined;updateQuestion(s.id,q.id,{type,points:type==='verbes_trous'?0:Number(q.points)||1,verbes_trous:vt,answer_key:type==='qcm'?{correctOptionId:''}:type==='reorder'?{correctOrder:[]}:type==='verbes_trous'?{phrases:[]}:{acceptedAnswers:[]},options:type==='qcm'?(q.options||[{id:makeId(),label:'Option A'},{id:makeId(),label:'Option B'}]):undefined,items:type==='reorder'?(q.items||[{id:makeId(),text:'Élément 1'},{id:makeId(),text:'Élément 2'}]):undefined});}}><option value="qcm">QCM / Vrai-Faux</option><option value="text">Réponse courte / trous</option><option value="reorder">Réordonnement</option><option value="verbes_trous">Verbes à trous avec banque</option></select><button onClick={()=>updateSection(s.id,{questions:s.questions.filter(x=>x.id!==q.id)})} className="rounded-lg p-2 text-rose-600"><Trash2 size={14}/></button></div>
    <label className="mt-2 block max-w-[220px] text-xs font-semibold">Temps de réponse (secondes)<input type="number" min="1" max="3600" step="1" className="mt-1 w-full rounded-lg border p-2" value={q.time_limit_seconds??getDefaultWrittenQuestionTimeLimit(q)} onChange={e=>updateQuestion(s.id,q.id,{time_limit_seconds:Math.max(1,Math.min(3600,Number(e.target.value)||1))})}/></label>
     {q.type==='qcm'&&<div className="mt-2 grid gap-2 sm:grid-cols-2"><textarea rows={4} className="rounded-lg border p-2 text-xs" placeholder="Une option par ligne" value={(q.options||[]).map(o=>o.label).join('\n')} onChange={e=>{const opts=e.target.value.split('\n').filter(Boolean).map((label,i)=>({id:q.options?.[i]?.id||makeId(),label}));updateQuestion(s.id,q.id,{options:opts,answer_key:{...q.answer_key,correctOptionId:opts.some(o=>o.id===q.answer_key.correctOptionId)?q.answer_key.correctOptionId:opts[0]?.id||''}});}}/><label className="text-xs">Bonne réponse<select className="mt-1 w-full rounded-lg border p-2" value={q.answer_key.correctOptionId||''} onChange={e=>updateQuestion(s.id,q.id,{answer_key:{...q.answer_key,correctOptionId:e.target.value}})}>{(q.options||[]).map(o=><option key={o.id} value={o.id}>{o.label}</option>)}</select></label></div>}
    {q.type==='text'&&<div className="mt-2 grid gap-2 sm:grid-cols-2"><label className="text-xs">Réponses acceptées (une variante par ligne)<textarea rows={3} className="mt-1 w-full rounded-lg border p-2 text-xs" value={(q.answer_key.acceptedAnswers||[]).join('\n')} onChange={e=>updateQuestion(s.id,q.id,{answer_key:{...q.answer_key,acceptedAnswers:e.target.value.split('\n').filter(Boolean),answers:undefined}})}/></label><label className="text-xs">Réponses multi-trous (JSON, une liste de variantes par trou)<textarea rows={3} className="mt-1 w-full rounded-lg border p-2 font-mono text-xs" placeholder='[["sono"],["ho"]]' value={answerJsonDraft[q.id]??(q.answer_key.answers?JSON.stringify(q.answer_key.answers):'')} onChange={e=>{setAnswerJsonDraft({...answerJsonDraft,[q.id]:e.target.value});try{const parsed=e.target.value?JSON.parse(e.target.value):undefined;updateQuestion(s.id,q.id,{answer_key:{...q.answer_key,answers:parsed},blank_count:parsed?.length||1});}catch{/* conserver la saisie brute jusqu’à la fin du JSON */}}}/></label></div>}
    {q.type==='reorder'&&<label className="mt-2 block text-xs">Éléments dans l’ordre correct (un par ligne)<textarea rows={4} className="mt-1 w-full rounded-lg border p-2 text-xs" value={(q.items||[]).map(x=>x.text).join('\n')} onChange={e=>{const items=e.target.value.split('\n').filter(Boolean).map((text,i)=>({id:q.items?.[i]?.id||makeId(),text}));updateQuestion(s.id,q.id,{items,answer_key:{correctOrder:items.map(x=>x.id)}});}}/></label>}
    {q.type==='verbes_trous'&&<VerbesTrousEditor definition={q.verbes_trous||{titre:'',consigne:'',points_par_phrase:3,banque:[],phrases:[]}} answerKey={(q.answer_key.phrases||[]).map(p=>({...p,verbe:p.verbe||'',reponses:p.reponses||[]}))} onChange={(definition,phrases)=>updateQuestion(s.id,q.id,{verbes_trous:definition,answer_key:{...q.answer_key,phrases},points:definition.phrases.length*3})}/>} 
    <div className="mt-2 flex flex-wrap gap-3">{q.type!=='verbes_trous'&&<label className="flex items-center gap-1 text-[11px]"><input type="checkbox" checked={!!q.manual_review} onChange={e=>updateQuestion(s.id,q.id,{manual_review:e.target.checked})}/>Correction manuelle</label>}<label className="flex items-center gap-1 text-[11px]"><input type="checkbox" checked={q.shuffle_options!==false} onChange={e=>updateQuestion(s.id,q.id,{shuffle_options:e.target.checked})}/>Mélanger options/éléments</label></div><label className="mt-2 block text-xs">Explication (visible seulement si la correction est publiée)<textarea rows={2} className="mt-1 w-full rounded-lg border p-2 text-xs" value={q.explanation||''} onChange={e=>updateQuestion(s.id,q.id,{explanation:e.target.value})}/></label>
    </div>)}</div>
    <button onClick={()=>updateSection(s.id,{questions:[...s.questions,createQuestion()]})} className="mt-3 rounded-lg border px-3 py-2 text-xs font-bold"><Plus className="mr-1 inline h-3.5 w-3.5"/>Question</button><p className="mt-2 text-[11px] text-slate-500">Questions : {s.questions.reduce((n,q)=>n+Number(q.points||0),0)} {s.points>0?'/ '+s.points+' points alloués':'points · sans plafond'}</p>
   </article>)}</div>
   <div className="flex flex-wrap justify-end gap-2 border-t pt-3"><button onClick={()=>setExam(null)} className="rounded-xl border px-4 py-2 text-sm">Annuler</button><button disabled={saving} onClick={()=>void save(false)} className="rounded-xl border px-4 py-2 text-sm font-bold"><Save className="mr-1 inline h-4 w-4"/>Brouillon</button><button disabled={saving} onClick={()=>void save(true)} className="rounded-xl bg-[#072a3f] px-4 py-2 text-sm font-bold text-white">{saving?'Enregistrement…':'Publier'}</button></div>
  </section>:selectedExamId?<section className={card+' space-y-4'}>
   <div className="flex flex-wrap items-center justify-between gap-2"><div><h2 className="font-bold text-[#072a3f]">Résultats, corrections et intégrité</h2><p className="text-xs text-slate-500">{selectedExam?.title||"Sujet"} · chaque tentative reste associée à sa version.</p></div><div className="flex flex-wrap gap-2"><button onClick={()=>void resetAttempts()} disabled={!['closed','grading'].includes(selectedExam?.status||'')||!attempts.length} title={!['closed','grading'].includes(selectedExam?.status||'')?"Clôturez le sujet avant la réinitialisation.":"Supprimer toutes les tentatives et leurs résultats."} className="rounded-lg border border-rose-300 px-3 py-2 text-xs font-semibold text-rose-700 disabled:opacity-40">Réinitialiser les tentatives</button><button onClick={exportResultsCsv} disabled={!attempts.length} className="rounded-lg border px-3 py-2 text-xs"><Download className="mr-1 inline h-3.5 w-3.5"/>CSV</button><button onClick={()=>setSelectedExamId('')} className="rounded-lg border px-3 py-2 text-xs">Retour</button></div></div>
   <div className="grid gap-2 sm:grid-cols-3"><div className="rounded-xl bg-[#f3f8fb] p-3"><p className="text-[10px] uppercase text-slate-500">Tentatives</p><p className="text-2xl font-black">{attempts.length}</p></div><div className="rounded-xl bg-[#f3f8fb] p-3"><p className="text-[10px] uppercase text-slate-500">Moyenne brute</p><p className="text-2xl font-black">{average.toFixed(2)}</p></div><div className="rounded-xl bg-[#f3f8fb] p-3"><p className="text-[10px] uppercase text-slate-500">À corriger</p><p className="text-2xl font-black">{attempts.filter(a=>a.status==='needs_review').length}</p></div></div>
   <div className="rounded-xl border p-3"><h3 className="text-xs font-bold text-[#072a3f]">Performance par section</h3><div className="mt-2 grid gap-2 sm:grid-cols-2">{sectionStats.map(s=>{const version=definitionData?.versions?.find((v:any)=>v.status==='published');const section=(definitionData?.versions||[]).flatMap((v:any)=>v.written_exam_sections||[]).find((x:any)=>x.id===s.id);return <div key={s.id} className="rounded-lg bg-slate-50 p-2 text-xs"><div className="flex justify-between gap-2"><span>{section?.title||'Section'}</span><strong>{s.score.toFixed(1)} / {s.max.toFixed(1)}</strong></div><div className="mt-1 h-1.5 rounded bg-slate-200"><div className="h-1.5 rounded bg-[#2fa36b]" style={{width:s.rate+'%'}}/></div></div>;})}</div></div>
   <div className="overflow-x-auto"><table className="w-full min-w-[620px] text-left text-xs"><thead><tr className="border-b text-slate-500"><th className="p-2">Élève</th><th className="p-2">Tentative</th><th className="p-2">Statut</th><th className="p-2">Score brut</th><th className="p-2">Normalisé</th><th className="p-2"></th></tr></thead><tbody>{attempts.map(a=><tr key={a.id} className="border-b"><td className="p-2 font-semibold">{a.students?.first_name} {a.students?.last_name}</td><td className="p-2">{a.attempt_number}</td><td className="p-2">{a.status}</td><td className="p-2">{a.raw_score===null?'—':a.raw_score+' / '+a.raw_max}</td><td className="p-2">{a.normalized_score??'—'}</td><td className="p-2"><button onClick={()=>{setSelectedAttempt(a);const version=definitionData?.versions?.find((v:any)=>v.id===a.version_id);const questions=(version?.written_exam_sections||[]).flatMap((s:any)=>(s.written_exam_questions||[]).filter((q:any)=>q.manual_review));setManualQuestions(questions);setManualScores(Object.fromEntries(questions.map((q:any)=>[q.id,Number(a.manual_scores?.[q.id]??0)])));setExpressionWritingScore(a.expression_writing_score==null?'':String(a.expression_writing_score));}} className="rounded-lg border px-2 py-1">Détails</button></td></tr>)}</tbody></table></div>
   {selectedAttempt&&<div className="rounded-xl border p-3"><div className="flex flex-wrap items-center justify-between gap-2"><h3 className="font-bold">{selectedAttempt.students?.first_name} {selectedAttempt.students?.last_name}</h3><button type="button" onClick={()=>downloadWrittenExamCopyPdf(selectedAttempt,definitionData?.versions?.find((v:any)=>v.id===selectedAttempt.version_id))} className="rounded-lg bg-[#072a3f] px-3 py-2 text-xs font-bold text-white"><Download className="mr-1 inline h-3.5 w-3.5"/>Télécharger la feuille PDF</button></div><p className="mt-1 text-xs text-slate-500">Début : {new Date(selectedAttempt.started_at).toLocaleString()} · Remise : {selectedAttempt.submitted_at?new Date(selectedAttempt.submitted_at).toLocaleString():'—'}</p><div className="mt-3 space-y-2">{(selectedAttempt.written_exam_section_results||[]).map((s:any)=>{const version=definitionData?.versions?.find((v:any)=>v.id===selectedAttempt.version_id);const section=(version?.written_exam_sections||[]).find((x:any)=>x.id===s.section_id);return <div key={s.id} className="flex justify-between border-b py-2 text-xs"><span>{section?.title||'Section'}</span><strong>{s.raw_score} / {s.raw_max}</strong></div>;})}</div><WrittenExamCopy attempt={selectedAttempt} version={definitionData?.versions?.find((v:any)=>v.id===selectedAttempt.version_id)} manualScores={manualScores} onManualScore={(id,value)=>setManualScores(previous=>({...previous,[id]:value}))}/>{Number(definitionData?.versions?.find((v:any)=>v.id===selectedAttempt.version_id)?.expression_writing_max_points||0)>0&&<div className="mt-3 rounded-xl border border-[#b9d8c9] bg-[#f6fbf8] p-3"><h4 className="font-bold text-[#072a3f]">Expression écrite</h4><p className="mt-1 text-xs text-slate-600">Saisissez la note attribuée après correction de la production écrite de l’élève. Cette note complète automatiquement les autres points pour obtenir une note finale sur 100.</p><label className="mt-2 block text-xs font-semibold">Note obtenue (/{Number(definitionData?.versions?.find((v:any)=>v.id===selectedAttempt.version_id)?.expression_writing_max_points||0)})<input type="number" min="0" max={Number(definitionData?.versions?.find((v:any)=>v.id===selectedAttempt.version_id)?.expression_writing_max_points||0)} step="0.5" value={expressionWritingScore} onChange={e=>setExpressionWritingScore(e.target.value)} className="mt-1 w-full rounded-lg border p-2 text-sm" placeholder="Saisir la note"/></label></div>}<button onClick={()=>void grade()} disabled={!manualQuestions.length&&!(Number(definitionData?.versions?.find((v:any)=>v.id===selectedAttempt.version_id)?.expression_writing_max_points||0)>0)} className="mt-3 rounded-xl bg-[#072a3f] px-3 py-2 text-xs font-bold text-white disabled:opacity-40">Enregistrer les notes et finaliser la correction</button></div>}
   <div className="flex flex-wrap items-center justify-between gap-2 border-t pt-3"><span className="text-xs text-slate-500"><ShieldAlert className="mr-1 inline h-4 w-4"/>Événements d’intégrité : {events.length}; ce sont des signaux, pas des preuves.</span><button disabled={attempts.some(a=>Number(a.expression_writing_max_points||0)>0&&a.expression_writing_score==null)} title={attempts.some(a=>Number(a.expression_writing_max_points||0)>0&&a.expression_writing_score==null)?'Saisissez d’abord toutes les notes d’expression écrite.':''} onClick={async()=>{try{await writtenExamService.publishResults(selectedExamId);setMessage('Résultats publiés.');await openResults(selectedExamId);}catch(e){setError(e instanceof Error?e.message:'Publication impossible.');}}} className="rounded-xl bg-emerald-700 px-4 py-2 text-xs font-bold text-white disabled:cursor-not-allowed disabled:opacity-40">{attempts.some(a=>Number(a.expression_writing_max_points||0)>0&&a.expression_writing_score==null)?'Notes d’expression à saisir':'Publier les résultats'}</button></div>
   {events.length>0&&<div className="max-h-48 overflow-auto rounded-xl bg-amber-50 p-3 text-xs"><h3 className="font-bold">Journal d’intégrité</h3>{events.map(ev=><p key={ev.id} className="mt-1">{new Date(ev.occurred_at).toLocaleString()} · {ev.event_type}</p>)}</div>}
  </section>:<>
   <div className="grid gap-3 sm:grid-cols-2"><button onClick={()=>start(L135_TEMPLATE)} className={card+' text-left hover:border-[#2fa36b]'}><p className="text-xs font-bold uppercase text-[#2fa36b]">Modèle B1</p><h2 className="mt-1 font-bold">L135 – 90 points</h2><p className="mt-1 text-sm text-slate-500">Compréhension 20 · Grammaire 50 · Vocabulaire 10 · Réordonnement 10 · 1 h 30</p></button><button onClick={()=>start(A1_TEMPLATE)} className={card+' text-left hover:border-[#2fa36b]'}><p className="text-xs font-bold uppercase text-[#2fa36b]">Modèle A1</p><h2 className="mt-1 font-bold">Esame bianco – 80 points</h2><p className="mt-1 text-sm text-slate-500">Compréhension 20 · Grammaire 25 · Vocabulaire 15 · Complétion 20 · 1 h 10 · /80</p></button></div>
   <section className={card+" sm:p-5"}><div className="flex flex-wrap items-center justify-between gap-2"><Layers3 className="text-[#2fa36b]"/><h2 className="font-bold">Examens enregistrés</h2></div>{loading?<p className="py-6 text-sm text-slate-500">Chargement…</p>:exams.length===0?<p className="py-6 text-sm text-slate-500">Aucun examen. Créez un sujet ou partez d’un modèle.</p>:<div className="mt-3 divide-y">{exams.map(item=><div key={item.id} className="flex flex-col gap-3 py-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-semibold">{item.title}</p><p className="text-xs text-slate-500">{item.level||'—'} · {item.duration_minutes} min · {item.status} · {(item.written_exam_versions||[]).length} version(s)</p><p className="text-xs text-slate-500">Classes : {(item.written_exam_classes||[]).map((row:any)=>classes.find(c=>c.id===row.class_id)?.name||'Classe').join(', ')||'Aucune classe assignée'}</p></div><div className="grid grid-cols-2 gap-2 sm:flex sm:flex-wrap"><button onClick={()=>void edit(item.id)} className="rounded-lg border px-3 py-2 text-xs font-bold">Modifier / version</button><button onClick={()=>void openResults(item.id)} className="rounded-lg border px-3 py-2 text-xs font-bold">Résultats</button><button onClick={async()=>{try{await writtenExamService.close(item.id);await refresh();}catch(e){setError(e instanceof Error?e.message:'Clôture impossible.');}}} className="rounded-lg border px-3 py-2 text-xs">Clôturer</button></div></div>)}</div>}</section>
  </>}
 </div>;
};
